-- Read-only canonical EPIPHANY Phase 0 catalog snapshot.
-- Excludes player rows and redacts developer email literals.
-- Run against the hosted project through a read-only SQL connector to refresh the
-- reference, and against the disposable local stack in CI for exact contract comparison.
SELECT jsonb_build_object(
'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations WHERE version IN ('20261023233115','20261024122251','20261030091511','20261030101059','20261030201651','20261030201953','20261030202518','20261030202723','20261030221913')),
'tables',(SELECT jsonb_agg(jsonb_build_object('table_name',t.table_name,'columns',(SELECT jsonb_agg(jsonb_build_object('name',c.column_name,'type',c.data_type,'nullable',c.is_nullable,'default',c.column_default,'ordinal',c.ordinal_position) ORDER BY c.ordinal_position) FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name=t.table_name)) ORDER BY t.table_name) FROM information_schema.tables t WHERE t.table_schema='public' AND t.table_type='BASE TABLE' AND t.table_name IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table_name',c.relname,'name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid)) ORDER BY c.relname,con.conname) FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'indexes',(SELECT jsonb_agg(jsonb_build_object('table_name',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname) FROM pg_indexes WHERE schemaname='public' AND tablename IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'public_policies',(SELECT jsonb_agg(jsonb_build_object('table_name',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',regexp_replace(coalesce(qual,''),'[[:alnum:]._%+-]+@[[:alnum:].-]+','<developer-email>','g'),'check',regexp_replace(coalesce(with_check,''),'[[:alnum:]._%+-]+@[[:alnum:].-]+','<developer-email>','g')) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public' AND tablename IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'storage_policies',(SELECT jsonb_agg(jsonb_build_object('name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',regexp_replace(coalesce(qual,''),'[[:alnum:]._%+-]+@[[:alnum:].-]+','<developer-email>','g'),'check',regexp_replace(coalesce(with_check,''),'[[:alnum:]._%+-]+@[[:alnum:].-]+','<developer-email>','g')) ORDER BY policyname) FROM pg_policies WHERE schemaname='storage' AND tablename='objects'),
'grants',(SELECT jsonb_agg(jsonb_build_object('grantee',grantee,'table_name',table_name,'privilege',privilege_type) ORDER BY table_name,grantee,privilege_type) FROM information_schema.role_table_grants WHERE table_schema='public' AND grantee IN ('anon','authenticated') AND privilege_type IN ('SELECT','INSERT','UPDATE','DELETE') AND table_name IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'rls',(SELECT jsonb_agg(jsonb_build_object('table_name',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND c.relname IN ('player_progress','player_profiles','player_posts','player_stories','epiphany_telemetry','epiphany_card_image_views','epiphany_assets','epiphany_asset_files','epiphany_asset_usages')),
'storage_buckets',(SELECT jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) ORDER BY id) FROM storage.buckets WHERE id IN ('player-avatars','character-art','epiphany-assets','epiphany-assets-private'))
) AS snapshot;
